create temp table task_fixture(key text primary key,value jsonb);grant all on task_fixture to authenticated;
create function pg_temp.set_actor(n integer) returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','52000000-0000-4000-8000-00000000000'||n,'role','authenticated','session_id','52100000-0000-4000-8000-00000000000'||n)::text,true);end $$;
create function pg_temp.op(op text,q jsonb,action_id uuid default gen_random_uuid()) returns jsonb language plpgsql as $$begin perform prepare_operational_review(auth.uid(),action_id,op,q);return execute_operational_review(auth.uid(),action_id);end $$;
create function pg_temp.definition(kind text) returns jsonb language sql as $$select jsonb_build_object('name','Synthetic '||kind,'category',case kind when 'before_visit' then 'preparation' when 'after_use' then 'turnover' else 'restock' end,'trigger',kind,'selectors',jsonb_build_object('types',case when kind='before_visit' then jsonb_build_array(jsonb_build_object('entry_id',(select value->>'id' from task_fixture where key='type'),'version_id',(select value#>>'{published,id}' from task_fixture where key='type'))) else '[]'::jsonb end,'resources',jsonb_build_array(jsonb_build_object('entry_id',(select value->>'id' from task_fixture where key='room'),'version_id',(select value#>>'{published,id}' from task_fixture where key='room')))),'due',jsonb_build_object('offset_minutes',case when kind='resource_day' then 0 else 15 end,'local_time',case when kind='resource_day' then '18:00' else null end,'dst_resolution','reject'),'eligible_roles',jsonb_build_array('STAFF','DVM','ADMIN'),'assignment','unassigned','assignee_id',null,'checklist',jsonb_build_array(jsonb_build_object('id','53000000-0000-4000-8000-000000000001','label','Synthetic approved SOP check','required',true)),'sop_reference','Synthetic approved SOP')$$;
create function pg_temp.templateq(id uuid,expected integer,action text,definition jsonb) returns jsonb language sql as $$select jsonb_build_object('id',id,'expected_version',expected,'action',action,'definition',definition,'review_note','Synthetic exact operational review','attest_review',true)$$;
create function pg_temp.booking(t jsonb,at_time timestamptz,id uuid default null,expected integer default null) returns jsonb language sql as $$select save_catalog_appointment(auth.uid(),gen_random_uuid(),id,expected,jsonb_build_object('type_version_id',t#>>'{published,id}','resource_version_id',(select value#>>'{published,id}' from task_fixture where key='room'),'client_id','52200000-0000-4000-8000-000000000001','pet_id','52300000-0000-4000-8000-000000000001','scheduled_at',at_time,'duration_minutes',30,'status','SCHEDULED','assigned_dvm_id','52000000-0000-4000-8000-000000000002','visit_type','clinic','address_snapshot','Synthetic','travel_before_minutes',0,'travel_after_minutes',0,'notes','Synthetic','reminder_offsets','[]'::jsonb,'override_note',''))$$;
create function pg_temp.taskq(t jsonb,act text,checked jsonb default '[]') returns jsonb language sql as $$select jsonb_build_object('id',t->>'id','expected_version',t->'version','context_hash',t->>'context_hash','action',act,'assignee_id',case when act='claim' then auth.uid() else null end,'checked_ids',checked,'note','Synthetic exact task action','due_at',null,'template_version_id',null)$$;
